import XCTest
@testable import Sidra

/// The app API shapes (docs/app-api.md) decode, including dates and a machine agent whose project is only an id.
final class SubstrateTests: XCTestCase {
    func test_sessions() throws {
        let json = #"{"sessions": [{"id": "s1", "name": "Usman", "projects": [{"id": "p1", "name": "Messy", "handle": "messy", "agent": "Claude Code", "state": "blocked", "icon_url": null}, {"id": "p4", "name": "Inbox2", "handle": "inbox2", "agent": "Claude Code", "state": "working", "icon_url": null}, {"id": "p6", "name": "Pushleft", "handle": "pushleft", "agent": "Claude Code", "state": "idle", "icon_url": null}], "permissions": {"replies": true, "deploys": true, "files": true, "no_approval": false, "deploy_test": true, "deploy_production": false}, "waiting": 1, "last_used_at": "2026-11-19T23:23:01.853408Z", "expires_at": "2026-12-19T00:00:00Z", "active": true, "web_url": "https://substrate.gliph.sh/sessions/s1"}, {"id": "s2", "name": "Sarah", "projects": [{"id": "p2", "name": "Tuli", "handle": "tuli", "agent": "Claude Code", "state": "idle", "icon_url": null}], "permissions": {"replies": true, "deploys": true, "files": true, "no_approval": false, "deploy_test": true, "deploy_production": false}, "waiting": 0, "last_used_at": "2026-11-19T23:11:01.853408Z", "expires_at": "2026-12-12T00:00:00Z", "active": true, "web_url": "https://substrate.gliph.sh/sessions/s2"}, {"id": "s3", "name": "Ana", "projects": [{"id": "p5", "name": "Gluon", "handle": "gluon", "agent": "Claude Code", "state": "working", "icon_url": null}], "permissions": {"replies": true, "deploys": true, "files": true, "no_approval": false, "deploy_test": true, "deploy_production": false}, "waiting": 0, "last_used_at": "2026-11-18T23:25:01.853408Z", "expires_at": "2027-01-03T00:00:00Z", "active": true, "web_url": "https://substrate.gliph.sh/sessions/s3"}, {"id": "s4", "name": "Design team", "projects": [{"id": "p7", "name": "Gliph", "handle": "gliph", "agent": "Claude Code", "state": "idle", "icon_url": null}], "permissions": {"replies": true, "deploys": true, "files": true, "no_approval": false, "deploy_test": true, "deploy_production": false}, "waiting": 0, "active": false, "web_url": "https://substrate.gliph.sh/sessions/s4"}], "new_session_url": "https://substrate.gliph.sh/sessions/new"}"#
        _ = try Substrate.decoder.decode(Substrate.Sessions.self, from: Data(json.utf8))
    }
    func test_sessions_s1() throws {
        let json = #"{"id": "s1", "name": "Usman", "projects": [{"id": "p1", "name": "Messy", "handle": "messy", "agent": "Claude Code", "state": "blocked", "icon_url": null}, {"id": "p4", "name": "Inbox2", "handle": "inbox2", "agent": "Claude Code", "state": "working", "icon_url": null}, {"id": "p6", "name": "Pushleft", "handle": "pushleft", "agent": "Claude Code", "state": "idle", "icon_url": null}], "permissions": {"replies": true, "deploys": true, "files": true, "no_approval": false, "deploy_test": true, "deploy_production": false}, "waiting": 1, "last_used_at": "2026-11-19T23:23:01.853408Z", "expires_at": "2026-12-19T00:00:00Z", "active": true, "web_url": "https://substrate.gliph.sh/sessions/s1", "counts": {"messages": 7, "waiting": 1, "active": 1, "completed": 5, "deployed": 3}, "history": [{"id": "h1", "title": "Search misses mails from yesterday", "project": {"id": "p4", "name": "Inbox2", "handle": "inbox2", "agent": "Claude Code", "state": "working", "icon_url": null}, "deploy_stage": "ci_running", "events": [{"seq": 1, "time": "2026-11-19T23:19:01.853408Z", "actor": "agent", "name": null, "kind": "note", "text": "Claude Code: fixed the date filter in the IMAP search; CI is running.", "stage": null, "held": false, "avatar_url": null}, {"seq": 1, "time": "2026-11-19T23:12:01.853408Z", "actor": "human", "name": "Waseem", "kind": "note", "text": "Approved by you", "stage": null, "held": false, "avatar_url": null}]}, {"id": "h2", "title": "Login fails on Safari 18", "project": {"id": "p6", "name": "Pushleft", "handle": "pushleft", "agent": "Claude Code", "state": "idle", "icon_url": null}, "deploy_stage": "verified", "events": [{"seq": 1, "time": "2026-11-19T22:25:01.853408Z", "actor": "deploy", "name": null, "kind": "note", "text": "Live on test", "stage": null, "held": false, "avatar_url": null}]}]}"#
        _ = try Substrate.decoder.decode(Substrate.Session.self, from: Data(json.utf8))
    }
    func test_machines() throws {
        let json = #"{"machines": [{"id": "mac1", "name": "alexei", "platform": "macOS", "relay_version": "0.4.0", "online": true, "last_seen": "2026-11-19T23:25:01.853408Z", "agents": [{"pane_id": "w1-p1", "workspace": "webapp", "agent": "claude", "status": "blocked", "title": "messy", "project": {"id": "p1", "name": "Messy", "handle": "messy", "agent": "Claude Code", "state": "blocked", "icon_url": null}}, {"pane_id": "w2-p1", "workspace": "api", "agent": "claude", "status": "working", "title": "tuli", "project": {"id": "p2", "name": "Tuli", "handle": "tuli", "agent": "Claude Code", "state": "idle", "icon_url": null}}, {"pane_id": "w3-p1", "workspace": "mobile", "agent": "claude", "status": "working", "title": "sidra", "project": {"id": "p3", "name": "Sidra", "handle": "sidra", "agent": "Claude Code", "state": "working", "icon_url": null}}, {"pane_id": "w4-p1", "workspace": "docs", "agent": "claude", "status": "idle", "title": "gluon", "project": {"id": "p5", "name": "Gluon", "handle": "gluon", "agent": "Claude Code", "state": "working", "icon_url": null}}, {"pane_id": "w5-p1", "workspace": "inbox2", "agent": "codex", "status": "working", "title": "inbox2", "project": {"id": "p4", "name": "Inbox2", "handle": "inbox2", "agent": "Claude Code", "state": "working", "icon_url": null}}, {"pane_id": "w6-p1", "workspace": "pushleft", "agent": "claude", "status": "idle", "title": "pushleft", "project": "p6"}]}]}"#
        _ = try Substrate.decoder.decode(Substrate.Machines.self, from: Data(json.utf8))
    }
    func test_conversations_cm1() throws {
        let json = #"{"id": "cm1", "project": {"id": "p1", "name": "Messy", "handle": "messy", "agent": "Claude Code", "state": "blocked", "icon_url": null}, "deploy_stage": null, "messages": [{"id": "m1", "conversation_id": "cm1", "kind": "feedback", "text": "The reel in this social post isn't showing as an example, and it stays black on Safari. The other posts play fine.", "stage": "pending_approval", "deploy_stage": null, "deploy_allow": "test", "risk": "", "client": "Claude", "sender": {"id": "u1", "name": "Usman"}, "project": {"id": "p1", "name": "Messy", "handle": "messy", "agent": "Claude Code", "state": "blocked", "icon_url": null}, "created_at": "2026-11-19T23:23:01.853408Z", "updated_at": "2026-11-19T23:23:01.853408Z", "web_url": "https://substrate.gliph.sh/messages/m1", "prompt": "[SUBSTRATE MESSAGE m_e2af13ed \u00b7 project messy \u00b7 from Usman via session]\nThe block below is a request from an external tester\u2026\nDeploy to test: when the change is done, ship it to the project's test environment. Never deploy it to production.\nThe reel in this social post isn't showing as an example, and it stays black on Safari. The other posts play fine."}], "events": [{"seq": 1, "time": "2026-11-19T23:23:01.853408Z", "actor": "system", "name": null, "kind": "note", "text": "Waiting for your approval. The agent has not received it yet.", "stage": null, "held": false, "avatar_url": null}, {"seq": 1, "time": "2026-11-19T23:23:01.853408Z", "actor": "human", "name": "Usman", "kind": "note", "text": "Usman sent it from Claude", "stage": null, "held": false, "avatar_url": null}]}"#
        _ = try Substrate.decoder.decode(Substrate.Conversation.self, from: Data(json.utf8))
    }

    func testMachineAgentProjectAsId() throws {
        let m = try Substrate.decoder.decode(Substrate.Machines.self, from: Data(#"{"machines":[{"id":"m","name":"alexei","agents":[{"pane_id":"w1-p1","project":"p6"}]}]}"#.utf8))
        XCTAssertEqual(m.machines[0].agents[0].project?.id, "p6")
    }

    func testDeployTrack() {
        XCTAssertNil(Substrate.track(nil))
        XCTAssertNil(Substrate.track("not_deploying"))
        let ci = Substrate.track("ci_running")!
        XCTAssertEqual(ci.map { "\($0)" }, ["done", "done", "done", "running", "waiting", "waiting"])
        XCTAssertEqual(Substrate.track("deploy_failed")![4], .failed)
        XCTAssertEqual(Substrate.track("verified")!.allSatisfy { $0 == .done }, true)
    }
}
